    ); // Process String Limit (cont.)
    ts.eval(
      '\nFindAndReplace(Locals.tmpString, "\\n", "<BR>")',
    ); // Process String Limit (cont.)
  }
  if (ts.cond('PropertyExists("Parameters.Step.Limits.String") ')) {
