      'Parameters.DocResult += Locals.RowHTML+ Locals.PropColHTML +\n	Str(GetResourceString("SEQ_FILE_DOC", "DOC_STEP_LIMIT_STRING"), "%-30s") +\n	Locals.ValColHTML + Locals.tmpString + "\\n"\n',
    ); // String Limit
