      'Parameters.DocResult += Locals.RowHTML+ Locals.PropColHTML +\n	Str(GetResourceString("SEQ_FILE_DOC", "DOC_STEP_EXEC_FLOW"), "%-30s") +\n	Locals.ValColHTML +\n	"<XMP>" + Locals.ExecFlow + "</XMP>" + "\\n"\n',
    ); // Execution Flow
  }
  ts.eval('Parameters.DocResult += "</TABLE></BLOCKQUOTE>\\n"'); // Step Footer
}

/// Sequence `Write Subproperties`.
Future<void> writeSubproperties({
  dynamic root,
  String docResult = '',
  String parentPropLookupStr = '',
  bool isRecursiveCall = false,
  dynamic docOptions,
}) async {
  int numSubproperties = 0; // Num — default: 0
  int i = 0; // Num — default: 0
  String subpropName = ''; // Str
  String subpropLookupStr = ''; // Str
  bool isHidden = false; // Bool — default: false
  int subpropFlags = 0; // Num — default: 0

  //   Return Value -> Locals.NumSubproperties
  //   lookupString <- Parameters.ParentPropLookupStr
  throw UnimplementedError(
    'cModule call: GetNumSubProperties',
  ); // GetNumSubProperties [Action]
  // goto -> <End>
  if (i == numSubproperties) {
    // precondition of Goto End When Done
    throw UnimplementedError(
      'step type Goto: action not exported yet',
    ); // Goto End When Done [Goto]
  }
  //   Return Value -> Locals.SubpropName
  //   lookupString <- Parameters.ParentPropLookupStr
  //   index <- Locals.i
  //   options <- 0
  throw UnimplementedError(
    'cModule call: GetSubPropName',
  ); // GetSubPropName [Action]
  ts.eval(
    '( Parameters.ParentPropLookupStr != "" ) ?\n	(Locals.SubpropLookupStr = Parameters.ParentPropLookupStr + "." + Locals.SubpropName ) :\n	(Locals.SubpropLookupStr = Locals.SubpropName )\n',
  ); // BuildNewLookupStr
  //   Return Value -> Locals.SubpropFlags
  //   lookupString <- Locals.SubpropLookupStr
  //   options <- 0
  throw UnimplementedError('cModule call: GetFlags'); // GetFlags [Action]
  ts.eval(
    '(Locals.SubpropFlags & 0x8) ? (Locals.IsHidden = true) : (Locals.IsHidden = false)',
  ); // IsHidden
  // status expression: (Step.Result.Status == "Done" && (Step.TS.SData.ThreadOpt == 0 || Step.TS.SData.ThreadOpt == 3)) ? "Passed" : Step.Result.Status
  if (ts.cond(
    'AnyOf(Locals.IsHidden == false, Parameters.DocOptions.ShowHidden)',
  )) {
    // precondition of DisplayProperty
    await writePropertyDetails(); // DisplayProperty
  }
  // status expression: (Step.Result.Status == "Done" && (Step.TS.SData.ThreadOpt == 0 || Step.TS.SData.ThreadOpt == 3)) ? "Passed" : Step.Result.Status
  if (ts.cond(
    'AllOf(AnyOf(Locals.IsHidden == false, Parameters.DocOptions.ShowHidden), Parameters.DocOptions.ShowSubproperties)',
  )) {
    // precondition of DisplaySubpropertiesOfSubproperty
    await writeSubproperties(); // DisplaySubpropertiesOfSubproperty
  }
  i += 1; // Increment index
  if (isRecursiveCall == false) {
    // precondition of Update Percent Done
    throw UnimplementedError(
      'cModule call: Update Percent Done',
    ); // Update Percent Done [Action]
  }
  // goto -> Goto End When Done
  throw UnimplementedError(
    'step type Goto: action not exported yet',
  ); // Loop back around [Goto]
}

/// Sequence `Write Array Elements`.
Future<void> writeArrayElements({
  dynamic root,
  String docResult = '',
  String arrayPropLookupStr = '',
  dynamic docOptions,
}) async {
  String currentArrayIndex = ''; // Str
  int currentOffset = 0; // Num — default: 0
  int numElements = 0; // Num — default: 0
  String rowHtml = '<TR>'; // Str
  String colHtml =
      '<TD WIDTH=33% colspan=3 NOWRAP=NOWRAP BGCOLOR=LIGHTBLUE>'; // Str

  //   lookupString <- Parameters.ArrayPropLookupStr
  //   options <- 0
  //   lowerBounds [out]
  //   upperBounds [out]
  //   numElements -> Locals.NumElements
  //   elementType [out]
  throw UnimplementedError(
    'cModule call: GetNumElements',
  ); // GetNumElements [Action]
  // label: --- Start of Loop ---
  // goto -> --- Max Num Array Elements Msg ---
  if (ts.cond(
    'AllOf(Locals.CurrentOffset == Parameters.DocOptions.MaxNumArrayElementsToShow, Locals.CurrentOffset != Locals.NumElements)',
  )) {
    // precondition of Check for Max Num Array Elements
    throw UnimplementedError(
      'step type Goto: action not exported yet',
    ); // Check for Max Num Array Elements [Goto]
  }
  // goto -> <End>
  if (currentOffset == numElements) {
    // precondition of Goto End When Done
    throw UnimplementedError(
      'step type Goto: action not exported yet',
    ); // Goto End When Done [Goto]
  }
  //   Return Value -> Locals.CurrentArrayIndex
  //   lookupString <- Parameters.ArrayPropLookupStr
  //   options <- 0
  //   offset <- Locals.CurrentOffset
  throw UnimplementedError(
    'cModule call: GetArrayIndexFromOffset',
  ); // GetArrayIndexFromOffset [Action]
  // status expression: (Step.Result.Status == "Done" && (Step.TS.SData.ThreadOpt == 0 || Step.TS.SData.ThreadOpt == 3)) ? "Passed" : Step.Result.Status
  await writePropertyDetails(); // DisplayProperty
  // status expression: (Step.Result.Status == "Done" && (Step.TS.SData.ThreadOpt == 0 || Step.TS.SData.ThreadOpt == 3)) ? "Passed" : Step.Result.Status
  await writeSubproperties(); // DisplaySubproperties
  currentOffset += 1; // Inc Loop Var
  // goto -> --- Start of Loop ---
  throw UnimplementedError(
    'step type Goto: action not exported yet',
  ); // Loop back around [Goto]
  // label: --- Max Num Array Elements Msg ---
  ts.eval(
    'Parameters.DocResult += Locals.RowHTML+ Locals.ColHTML +\n	Parameters.ArrayPropLookupStr + "[...] --- " +\nResStr("SEQ_FILE_DOC", "DOC_MAX_ARRAY_DISPLAY_EXCEEDED") \n',
  ); // Add Max Exceeded Msg
}

/// Sequence `Write Property Details`.
Future<void> writePropertyDetails({
  String docResult = '',
  dynamic root,
  String propertyToDisplayName = '',
  dynamic docOptions,
}) async {
  int valueType = 0; // Num — default: 0
  bool isObject = false; // Bool — default: false
  bool isArray = false; // Bool — default: false
  String typeName = ''; // Str
  String subpropValue = '...'; // Str
  int subpropFlags = 0; // Num — default: 0
  String byRefStr = ''; // Str
  String rowHtml = '<TR>'; // Str
  String propColHtml = '<TD WIDTH=33% NOWRAP=NOWRAP BGCOLOR=LIGHTBLUE>'; // Str
  String typeColHtml = '<TD WIDTH=33% BGCOLOR=GOLDENROD>'; // Str
  String valColHtml = '<TD WIDTH=33% BGCOLOR=LIGHTGREEN>'; // Str
  String unused = ''; // Str

  //   Return Value -> Locals.valueType
  //   lookupString <- Parameters.PropertyToDisplayName
  //   options <- 0
  //   isObject -> Locals.isObject
  //   isArray -> Locals.isArray
  //   typeName -> Locals.typeName
  throw UnimplementedError('cModule call: GetTypeInfo'); // GetTypeInfo [Action]
  // Normally Evaluate() should only fail if the property name has invalid characters in it.
  // label: --- Test Evaluate Error ---
  // custom flow: if (True) Goto -> <End> else Next
  // ignores run-time errors
  // failure does NOT fail the sequence
  ts.eval(
    'Evaluate("Parameters.Root." + Parameters.PropertyToDisplayName)',
  ); // TryToEvaluate
  if (ts.cond(
    'RunState.Sequence.Main["TryToEvaluate"].Result.Status == "Error"',
  )) {
    // precondition of Document Error
    subpropValue = runState
        .Sequence
        .Main["TryToEvaluate"]
        .Result
        .Error
        .Msg; // Document Error
  }
  // goto -> --- Skip Evaluate ---
  if (ts.cond(
    'RunState.Sequence.Main["TryToEvaluate"].Result.Status == "Error"',
  )) {
    // precondition of Skip Evaluate
    throw UnimplementedError(
      'step type Goto: action not exported yet',
    ); // Skip Evaluate [Goto]
  }
  typeName = root.GetPropertyObject(
    propertyToDisplayName,
    0x0,
  ).Type.DisplayString; // GetTypeNameForDisplay
  // Get the value of a number, boolean or activex property
  if (ts.cond(
    'AnyOf(Locals.valueType == 2, Locals.valueType == 3, Locals.valueType == 5)',
  )) {
    // precondition of GetSubPropValue1
    ts.eval(
      'Locals.SubpropValue = Str(Evaluate("Parameters.Root." + Parameters.PropertyToDisplayName))',
    ); // GetSubPropValue1
  }
  // Get the value of a string property
  if (valueType == 1) {
    // precondition of GetSubPropValue2
    ts.eval(
      'Locals.SubpropValue = "\\"" + Evaluate("Parameters.Root." + Parameters.PropertyToDisplayName) + "\\""',
    ); // GetSubPropValue2
  }
  // Get the value of an enum property
  if (ts.cond('Locals.valueType == PropValType_Enum')) {
    // precondition of GetSubPropValue7
    ts.eval(
      ' Evaluate("Parameters.Root." + Parameters.PropertyToDisplayName).GetDisplayNames("", PropOption_NoOptions, Locals.Unused, Locals.SubpropValue)',
    ); // GetSubPropValue7
  }
  // label: --- Skip Evaluate ---
  ts.eval(
    'FindAndReplace(Locals.SubpropValue, "<", "&lt;")',
  ); // Process SubpropValue
  ts.eval(
    '\nFindAndReplace(Locals.SubpropValue, ">", "&gt;")',
  ); // Process SubpropValue (cont.)
  ts.eval(
    '\nFindAndReplace(Locals.SubpropValue, "\\n", "<BR>")',
  ); // Process SubpropValue (cont.)
  //   Return Value -> Locals.SubpropFlags
  //   lookupString <- Parameters.PropertyToDisplayName
  //   options <- 0
  throw UnimplementedError('cModule call: GetFlags'); // GetFlags [Action]
  ts.eval(
    '(Locals.SubpropFlags & 0x4) ? ( Locals.ByRefStr = " (" + ResStr("SEQUENCING ADAPTER", "PASS_BYREFERENCE") + ")" ) : ( Locals.ByRefStr = "" )',
  ); // IsByRef
  ts.eval(
    'Parameters.DocResult += Locals.RowHTML+ Locals.PropColHTML +\n	Parameters.PropertyToDisplayName +\n	Locals.TypeColHTML +\n	Locals.typeName + Locals.ByRefStr +\n	Locals.ValColHTML +\n	Locals.SubpropValue + "\\n"\n',
  ); // Add Display String
  // status expression: (Step.Result.Status == "Done" && (Step.TS.SData.ThreadOpt == 0 || Step.TS.SData.ThreadOpt == 3)) ? "Passed" : Step.Result.Status
  if (ts.cond(
    'AllOf(Locals.isArray, Parameters.DocOptions.ShowArrayElements)',
  )) {
    // precondition of DisplayArrayElements
    await writeArrayElements(); // DisplayArrayElements
  }
}

